# Headless run of the five analyses (the .b.R classes) on the sample data and on edge cases.
# Run from the module root, best in jamovi's own R with the jamovi libraries:  Rscript tests/smoke.R
suppressMessages({library(jmvcore); library(R6); library(ggplot2)})
for (f in c("R/00jmv.R", "R/common.R", list.files("R", "^engine_.*[.]R$", full.names = TRUE), "R/guide.R", list.files("R", "[.]h[.]R$", full.names = TRUE), list.files("R", "[.]b[.]R$", full.names = TRUE))) source(f)
tr <- read.csv("data/sim_trial.csv", na.strings = "", stringsAsFactors = TRUE); cl <- read.csv("data/sim_cluster_trial.csv", stringsAsFactors = TRUE)
sm <- read.csv("data/sim_small_trial.csv", stringsAsFactors = TRUE)
tr$block <- factor(tr$block)
bad <- 0
run <- function(label, fn, data, expect_error = FALSE, ...) {
    a <- list(...)
    fm <- formals(fn)
    for (n in setdiff(names(fm)[vapply(fm, function(z) identical(z, quote(expr = )), logical(1))], c("data", names(a)))) a[n] <- list(NULL)
    t0 <- Sys.time()
    r <- tryCatch({ res <- do.call(fn, c(list(data = data), a)); invisible(capture.output(print(res))); "ok" }, error = function(e) paste("ERROR:", conditionMessage(e)))
    good <- if (expect_error) grepl("^ERROR", r) else r == "ok"
    cat(sprintf("%-52s %5.1fs  %s\n", label, as.numeric(difftime(Sys.time(), t0, units = "secs")), if (good) substr(r, 1, 80) else paste("UNEXPECTED:", r))); if (!good) bad <<- bad + 1
    invisible(NULL)
}
# ---- Treatment Effects
for (m in c("diff", "adjust", "lin")) run(paste("exeffect", m), exeffect, tr, outcome = "y1", treat = "arm", covs = c("baseline", "age", "female"), block = "block", method = m)
for (s in c("classical", "hc1", "hc2", "hc3")) run(paste("exeffect se", s), exeffect, tr, outcome = "y1", treat = "arm", se = s)
run("exeffect cluster CR2", exeffect, cl, outcome = "y", treat = "group", cluster = "school")
run("exeffect cluster CR1 + covariate", exeffect, cl, outcome = "y", treat = "group", cluster = "school", covs = "baseline", method = "adjust", se = "cr1")
run("exeffect control value, notes and guide", exeffect, tr, outcome = "y2", treat = "arm", control = "T1", showGuide = TRUE, showHelp = TRUE, level = 90)
run("exeffect CR2 without cluster (error)", exeffect, tr, TRUE, outcome = "y1", treat = "arm", se = "cr2")
run("exeffect bad control value (error)", exeffect, tr, TRUE, outcome = "y1", treat = "arm", control = "zzz")
run("exeffect missing treatment (hint)", exeffect, tr, outcome = "y1", treat = NULL)
d2 <- tr; d2$y1[1:30] <- NA
run("exeffect missing outcomes dropped", exeffect, d2, outcome = "y1", treat = "arm")
run("exeffect numeric treatment 0/1/2", exeffect, transform(tr, a = as.integer(arm) - 1), outcome = "y1", treat = "a")
# ---- Randomization Inference
run("exri small exact", exri, sm, outcome = "y", treat = "group", control = "control")
for (s in c("rank", "tstat")) run(paste("exri", s), exri, sm, outcome = "y", treat = "group", control = "control", stat = s)
run("exri blocked simulation, two arms", exri, tr, outcome = "y1", treat = "arm", block = "block", sims = 500, plot = TRUE)
run("exri hypothesised effect 0.3", exri, tr, outcome = "y1", treat = "arm", sims = 500, tau = 0.3)
run("exri cluster", exri, cl, outcome = "y", treat = "group", cluster = "school", sims = 500, control = "control")
run("exri notes and guide, no interval", exri, sm, outcome = "y", treat = "group", control = "control", ci = FALSE, showGuide = TRUE, showHelp = TRUE)
run("exri treatment varies within a cluster (error)", exri, transform(cl, group = factor(ifelse(student %% 2 == 0, "control", "treated"))), TRUE, outcome = "y", treat = "group", cluster = "school")
# ---- Multiple Outcomes
run("exmht defaults", exmht, tr, outcomes = c("y1", "y2", "y3", "y4"), treat = "arm", armTreat = "T2", covs = "baseline")
run("exmht all methods, blocks", exmht, tr, outcomes = c("y1", "y2", "y3"), treat = "arm", block = "block", sidak = TRUE, hochberg = TRUE, by = TRUE, wymax = TRUE, nperm = 300, nboot = 200)
run("exmht notes and guide", exmht, tr, outcomes = c("y1", "y2"), treat = "arm", showGuide = TRUE, showHelp = TRUE, nperm = 200, nboot = 200)
run("exmht one outcome (hint)", exmht, tr, outcomes = "y1", treat = "arm")
run("exmht no method (error)", exmht, tr, TRUE, outcomes = c("y1", "y2"), treat = "arm", bonf = FALSE, holm = FALSE, bh = FALSE, wymin = FALSE, rw = FALSE)
run("exmht bad treatment group (error)", exmht, tr, TRUE, outcomes = c("y1", "y2"), treat = "arm", armTreat = "zzz")
# ---- Power and Sample Size (no variables are needed; an empty frame stands in for the dataset)
for (md in c("power", "mde", "n")) run(paste("expower", md), expower, data.frame(), mode = md)
run("expower cluster design", expower, data.frame(), design = "cluster", mode = "n", effect = 0.25)
run("expower one-sided with covariates", expower, data.frame(), sided = "one", r2 = 0.3, ncov = 3, mode = "mde")
run("expower from data (sd, rho, R2)", expower, cl, useData = TRUE, dataOutcome = "y", dataCluster = "school", dataCovs = "baseline", design = "cluster")
run("expower notes and guide", expower, data.frame(), showGuide = TRUE, showHelp = TRUE, plot = TRUE)
run("expower data option without outcome (error)", expower, data.frame(), TRUE, useData = TRUE)
# ---- Bounds under Attrition
run("exlee T2 default", exlee, tr, outcome = "endline", treat = "arm", armTreat = "T2", nboot = 200)
run("exlee T1, tightened by block", exlee, tr, outcome = "endline", treat = "arm", armTreat = "T1", tight = "block", nboot = 200)
run("exlee direction chosen, notes and guide", exlee, tr, outcome = "endline", treat = "arm", armTreat = "T2", direction = "down", showGuide = TRUE, showHelp = TRUE, nboot = 200)
run("exlee control value and level", exlee, tr, outcome = "endline", treat = "arm", control = "T1", armTreat = "T2", level = 90, nboot = 200)
run("exlee no attrition difference", exlee, transform(tr, endline = y1), outcome = "endline", treat = "arm", armTreat = "T1", nboot = 200)
run("exlee wrong direction (error)", exlee, tr, TRUE, outcome = "endline", treat = "arm", armTreat = "T2", direction = "up", nboot = 100)
run("exlee bad treatment group (error)", exlee, tr, TRUE, outcome = "endline", treat = "arm", armTreat = "zzz")
run("exlee without outcome (hint)", exlee, tr, outcome = NULL, treat = "arm")
# ---- Subgroup Effects and Factorial Design
sg <- read.csv("data/sim_subgroup_trial.csv", stringsAsFactors = TRUE); fc <- read.csv("data/sim_factorial_trial.csv", stringsAsFactors = TRUE)
run("exsub default", exsub, sg, outcome = "y", treat = "arm", subgroups = c("gender", "agegroup", "region"))
run("exsub covariates, adjusted estimator, Benjamini-Hochberg", exsub, sg, outcome = "y", treat = "arm", subgroups = c("gender", "region"), covs = "baseline", method = "adjust", adjust = "bh")
run("exsub no adjustment, HC3, level 90, no plot", exsub, sg, outcome = "y", treat = "arm", subgroups = "gender", se = "hc3", adjust = "none", level = 90, plot = FALSE)
run("exsub clusters", exsub, transform(sg, school = id %% 40), outcome = "y", treat = "arm", subgroups = "gender", cluster = "school")
run("exsub notes and guide", exsub, sg, outcome = "y", treat = "arm", subgroups = "gender", showHelp = TRUE, showGuide = TRUE)
run("exsub three arms: pick two", exsub, transform(tr, gen = factor(ifelse(female == 1, "woman", "man"))), outcome = "y1", treat = "arm", control = "control", armTreat = "T2", subgroups = "gen")
run("exsub numeric subgroup variable", exsub, transform(tr, urbanl = female), outcome = "y1", treat = "arm", armTreat = "T1", subgroups = "urbanl")
run("exsub missing values", exsub, within(sg, { y[1:30] <- NA; gender[40:50] <- NA }), outcome = "y", treat = "arm", subgroups = c("gender", "agegroup"))
run("exsub no subgroup (hint)", exsub, sg, outcome = "y", treat = "arm", subgroups = NULL)
run("exsub CR1 without cluster (error)", exsub, sg, TRUE, outcome = "y", treat = "arm", subgroups = "gender", se = "cr1")
run("exsub outcome as subgroup (error)", exsub, sg, TRUE, outcome = "y", treat = "arm", subgroups = c("y", "gender"))
run("exfact default", exfact, fc, outcome = "savings", factorA = "message", factorB = "incentive", controlA = "none", controlB = "no")
run("exfact covariates", exfact, fc, outcome = "savings", factorA = "message", factorB = "incentive", covs = c("age", "baseline"))
run("exfact classical, HC1, level 90", exfact, fc, outcome = "savings", factorA = "incentive", factorB = "message", se = "hc1", level = 90)
run("exfact clusters", exfact, transform(fc, school = id %% 60), outcome = "savings", factorA = "message", factorB = "incentive", cluster = "school")
run("exfact notes and guide", exfact, fc, outcome = "savings", factorA = "message", factorB = "incentive", showHelp = TRUE, showGuide = TRUE)
run("exfact one level (error)", exfact, transform(fc, incentive = "yes"), TRUE, outcome = "savings", factorA = "message", factorB = "incentive")
run("exfact same factor twice (error)", exfact, fc, TRUE, outcome = "savings", factorA = "message", factorB = "message")
run("exfact empty cell (error)", exfact, fc[!(fc$message == "info" & fc$incentive == "yes"), ], TRUE, outcome = "savings", factorA = "message", factorB = "incentive")
run("exfact no factor (hint)", exfact, fc, outcome = "savings", factorA = "message", factorB = NULL)
# ---- Worst-Case Bounds
sp <- read.csv("data/sim_selection_program.csv", stringsAsFactors = TRUE)
run("exbounds random assignment, missing outcomes", exbounds, tr, outcome = "endline", treat = "arm", armTreat = "T2", mode = "random", nboot = 200)
run("exbounds random assignment, stated range, no plot", exbounds, tr, outcome = "endline", treat = "arm", armTreat = "T1", mode = "random", ymin = "-5", ymax = "5", plot = FALSE, nboot = 200)
run("exbounds selection, all four assumption sets", exbounds, sp, outcome = "employed", treat = "program", mode = "selection", ymin = "0", ymax = "1", nboot = 200, showHelp = TRUE, showGuide = TRUE)
run("exbounds selection, observed range, level 90", exbounds, sp, outcome = "employed", treat = "program", mode = "selection", level = 90, nboot = 200)
run("exbounds assumptions contradicted by the data", exbounds, transform(sp, program = ifelse(program == "yes", "no", "yes")), outcome = "employed", treat = "program", mode = "selection", ymin = "0", ymax = "1", nboot = 200)
run("exbounds missing outcomes dropped in the selection situation", exbounds, within(sp, employed[1:40] <- NA), outcome = "employed", treat = "program", mode = "selection", nboot = 200)
run("exbounds range not a number (error)", exbounds, sp, TRUE, outcome = "employed", treat = "program", ymin = "abc")
run("exbounds outcome outside the range (error)", exbounds, sp, TRUE, outcome = "employed", treat = "program", mode = "selection", ymin = "0.5", ymax = "2")
run("exbounds bad treatment group (error)", exbounds, sp, TRUE, outcome = "employed", treat = "program", armTreat = "zzz")
run("exbounds without a treatment (hint)", exbounds, sp, outcome = "employed", treat = NULL)
# ---- Balance and Attrition
run("exbalance full", exbalance, tr, treat = "arm", covs = c("baseline", "age", "female"), block = "block", outcome = "endline", nperm = 300)
run("exbalance without outcome", exbalance, tr, treat = "arm", covs = c("baseline", "income"), nperm = 200)
run("exbalance notes and guide", exbalance, tr, treat = "arm", covs = "baseline", showGuide = TRUE, showHelp = TRUE, nperm = 200)
run("exbalance covariate with missing values", exbalance, transform(tr, baseline = ifelse(id %% 10 == 0, NA, baseline)), treat = "arm", covs = c("baseline", "age"), outcome = "endline", nperm = 200)
run("exbalance no covariates (hint)", exbalance, tr, treat = "arm", covs = NULL)
cat(if (bad == 0) "\nAll checks passed.\n" else sprintf("\n%d check(s) failed.\n", bad))
if (bad > 0) quit(status = 1)
